record.field:
{
    "type": "object",
    "properties": {
        "action_key": {
            "type": "string",
            "description": "Key of the form action to describe (e.g. 'send_mail'). Empty string lists all available actions."
        }
    },
    "required": ["action_key"]
}

{
    "type": "object",
    "properties": {
        "form_selector": {
            "type": "string",
            "description": "CSS selector matching the form (or its section) on the page"
        },
        "action_key": {
            "type": "string",
            "description": "Key of the form action to wire, from \"Get Webform Info\""
        },
        "fields": {
            "type": "array",
            "description": "Hidden destination/preset values to set, only ever values the user approved. Empty when only switching the action.",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "type": "string",
                        "description": "Model field name"
                    },
                    "value": {
                        "type": "string",
                        "description": "The value; for a relational field, the numeric id of the targeted record"
                    }
                },
                "required": ["name", "value"]
            }
        }
    },
    "required": ["form_selector", "action_key", "fields"]
}
